import {withPool,transaction,readSeeds,fail} from './shared.mjs';
const selected=key=>key.startsWith('v2.')||['hero.title','campaign.heroIntro'].includes(key);
try{const seeds=await readSeeds();await withPool(db=>transaction(db,async client=>{let changed=0;for(const [locale,messages] of Object.entries(seeds))for(const [key,value] of Object.entries(messages)){if(!selected(key))continue;const result=await client.query(`INSERT INTO content_messages(locale,key,value) VALUES($1,$2,$3) ON CONFLICT(locale,key) DO UPDATE SET value=excluded.value,updated_at=now() WHERE content_messages.value IS DISTINCT FROM excluded.value`,[locale,key,value]);changed+=result.rowCount;}console.log(JSON.stringify({event:'product_redesign_applied',changed,scope:'Product redesign keys and homepage headline/intro only'}));}));}catch(error){fail(error);}
